import argparse
import asyncio
import os
from pathlib import Path

import carb
import omni.hydratexture
import omni.kit.renderer_capture
import omni.ui as ui
import omni.usd
import usdrt
from omni.kit.viewport.utility import create_viewport_window
from pxr import Sdf


def set_attribute(stage_path: str, attribute_name: str, value):
    if stage_path:
        carb.log_info(f"Setting attribute {attribute_name} to {value} on {stage_path}")
        fabric_stage = usdrt.Usd.Stage.Attach(omni.usd.get_context().get_stage_id())
        prim = fabric_stage.GetPrimAtPath(usdrt.Sdf.Path(stage_path))
        prim.GetAttribute(attribute_name).Set(value)


class PostProcessingTest:
    """Self-contained harness for RTX post-processing tests (no module-level globals)."""

    DEFAULT_RENDER_PRODUCTS = []
    DEFAULT_VIEWPORT_TYPES = []
    DEFAULT_EXIT_FRAME_COUNT = 200

    def __init__(self, usd_path: str, exit_frame_count: int | None = None, display_aov: str | None = None):
        # Basic state
        self.usd_path = usd_path
        self.exit_frame_count = exit_frame_count
        self.display_aov = display_aov
        self.render_products: list[str] = self.DEFAULT_RENDER_PRODUCTS.copy()
        self.viewport_types: list[str] = self.DEFAULT_VIEWPORT_TYPES.copy()
        self.window_count: int = len(self.render_products)
        self.viewports: list[dict] = []
        # Kit / Hydra interfaces
        self.usd_context = omni.usd.get_context()
        self.hydra_texture_factory = omni.hydratexture.acquire_hydra_texture_factory_interface()
        if self.hydra_texture_factory is None:
            raise ImportError("Failed to load hydra_texture_factory interface")
        self.renderer_capture = omni.kit.renderer_capture.acquire_renderer_capture_interface()
        if not self.renderer_capture:
            raise ImportError("Failed to load renderer_capture interface")

        # Pre-scan the USD file for configuration hints
        self._load_test_config_from_file()

    # ---------------------------------------------------------------------
    # Configuration helpers
    # ---------------------------------------------------------------------

    def _apply_test_config_dict(self, cfg):
        """Patch internal settings from a `testConfig` dictionary."""
        if not cfg:
            return

        if (rp := cfg.get("renderProducts")) is not None:
            self.render_products = [str(p) for p in rp]
        if (vt := cfg.get("viewport_types")) is not None:
            self.viewport_types = [str(t) for t in vt]
        if not self.exit_frame_count:
            self.exit_frame_count = self.DEFAULT_EXIT_FRAME_COUNT if not (ef := cfg.get("exitFrameCount")) else int(ef)

        # Guard against mismatches
        if len(self.render_products) != len(self.viewport_types):
            carb.log_warn(
                "testConfig mismatch: renderProducts and viewport_types lengths differ; truncating to min length"
            )
            n = min(len(self.render_products), len(self.viewport_types))
            self.render_products = self.render_products[:n]
            self.viewport_types = self.viewport_types[:n]
        self.window_count = len(self.render_products)

    def _load_test_config_from_file(self):
        """Read `testConfig` from the root layer before opening the stage."""
        layer = Sdf.Layer.FindOrOpen(self.usd_path)
        if not layer:
            carb.log_warn(f"Unable to open USD layer: {self.usd_path}")
            return
        self._apply_test_config_dict(layer.customLayerData.get("testConfig"))

    # ---------------------------------------------------------------------
    # Stage loading / runtime callbacks
    # ---------------------------------------------------------------------

    def on_stage_loading_done(self, result, err):
        if not result:
            carb.log_error("Stage file load failed")
            omni.kit.app.get_app().post_quit(result)
            return

        # Refresh config in case the layer was edited during load
        retVal = self._load_test_config_from_stage()
        if retVal != 0:
            omni.kit.app.get_app().post_quit(retVal)
            return
        self._run_test()

    def _load_test_config_from_stage(self):
        stage = self.usd_context.get_stage()
        if not stage:
            carb.log_error("Stage file load failed")
            return 1

        root_layer = stage.GetRootLayer()
        test_config = root_layer.customLayerData.get("testConfig")
        if not test_config:
            carb.log_error("No 'testConfig' found in customLayerData")
            return 1
        self._apply_test_config_dict(test_config)
        return 0

    # ---------------------------------------------------------------------
    # Rendering / viewport management
    # ---------------------------------------------------------------------

    async def _quit_after_delay(self, frames: int = 10):
        carb.log_info(f"All viewports done, quitting after {frames} frames")
        app = omni.kit.app.get_app()
        for i in range(frames):
            carb.log_info(f"Shutdown countdown: {frames - i}")
            await app.next_update_async()
        app.post_uncancellable_quit(0)

    def _on_render_done(self, event):
        for vp in self.viewports:
            hydra_texture = vp["hydra_texture"]
            if hydra_texture.get_event_key()["handle"] != event.payload["handle"]:
                continue
            frame_info = vp["hydra_texture"].get_frame_info(event.payload["result_handle"])
            if frame_info["frame_number"] > self.exit_frame_count and vp["rendering_sub"]:
                vp["rendering_sub"] = None
                asyncio.ensure_future(self._save_aovs_to_png(hydra_texture, event.payload["result_handle"]))
                self.window_count -= 1
                carb.log_info(f"windowCount: {self.window_count}")
                break
        if self.window_count == 0:
            asyncio.ensure_future(self._quit_after_delay())

    async def _save_aovs_to_png(self, hydra_texture, result_handle):
        # Determine capture path behaviour: file or directory
        capture_path_str = carb.settings.get_settings().get("/app/captureFrame/fileName")
        capture_path = Path(capture_path_str)
        carb.log_info(f"capture_path: {capture_path}")

        # Determine if the user meant a directory:
        # 1) Path already exists and is a dir
        # 2) String ends with a path separator ("/" or "\\")
        # 3) Path does NOT have an extension (empty suffix).
        if capture_path.is_dir() or capture_path_str.endswith(os.sep) or capture_path.suffix == "":
            base_path = capture_path
        else:
            base_path = capture_path.parent

        # Ensure base directory exists
        try:
            base_path.mkdir(parents=True, exist_ok=True)
        except Exception as e:
            carb.log_error(f"Failed to create directory {base_path}: {e}")

        render_product_name = Path(hydra_texture.get_render_product_path()).name
        frame_info = hydra_texture.get_frame_info(result_handle)
        all_aov_info = hydra_texture.get_aov_info(result_handle, include_texture=True)
        if not all_aov_info:
            carb.log_error("No AOV data found in render result")
            return
        carb.log_info(f"{render_product_name}: Found {len(all_aov_info)} AOVs in render results:")
        for aov in all_aov_info:
            texture = aov["texture"]
            carb.log_info(f"- '{aov['name']}' {texture['resolution']} {texture['format']}")
            rp_resource = texture["rp_resource"]
            if rp_resource:
                out_file = base_path / f"{render_product_name}_{aov['name']}_frame_{frame_info['frame_number']}.png"
                carb.log_info(f"Capturing frame to {out_file}")
                self.renderer_capture.capture_next_frame_rp_resource(filepath=str(out_file), resource=rp_resource)
                self.renderer_capture.wait_async_capture()
            else:
                carb.log_error(f"No RP resource found for {aov['name']}, skipping capture.")

    async def _create_viewports(self):
        carb.log_info("create_viewports")
        x_pos, y_pos = 12, 75
        width = height = 300
        for i in range(self.window_count):
            if i and i % 3 == 0:
                x_pos, y_pos = 12, y_pos + 312
            hydra_engine_type = "rtx"

            vp_dict = {"viewport": None, "hydra_texture": None, "rendering_sub": None}
            carb.log_info(f"Viewport {i} as '{self.viewport_types[i]}'")
            if self.viewport_types[i] == "texture":
                hydra_tex = self.hydra_texture_factory.create_hydra_texture(
                    name=f"Viewport {i}",
                    width=width,
                    height=height,
                    hydra_engine_name=hydra_engine_type,
                )
                hydra_tex.set_render_product_path(self.render_products[i])
                vp_dict["hydra_texture"] = hydra_tex
            else:  # window
                viewport = create_viewport_window(
                    name=f"Viewport {i}",
                    width=width,
                    height=height,
                    position_x=x_pos,
                    position_y=y_pos,
                    hydra_engine_options={},
                )
                x_pos += 312
                viewport.viewport_api.render_product_path = self.render_products[i]
                viewport.deferred_dock_in("Property", ui.DockPolicy.CURRENT_WINDOW_IS_ACTIVE)
                if self.display_aov:
                    viewport.viewport_api.display_render_var = str(self.display_aov)
                vp_dict["viewport"] = viewport
                # TODO: Find public API to access hydra_texture instead of using private member
                vp_dict["hydra_texture"] = viewport.viewport_api._hydra_texture

            # Subscribe to render completion
            vp_dict["rendering_sub"] = carb.eventdispatcher.get_eventdispatcher().observe_event(
                observer_name=f"Viewport {i}",
                event_name=omni.hydratexture.GLOBAL_EVENT_DRAWABLE_CHANGED,
                filter=vp_dict["hydra_texture"].get_event_key(),
                on_event=self._on_render_done,
            )

            self.viewports.append(vp_dict)

    def _run_test(self):
        carb.settings.get_settings().set_string("/rtx/rendermode", "RaytracedLighting")
        asyncio.ensure_future(self._create_viewports())

    # ---------------------------------------------------------------------
    # Public entry point
    # ---------------------------------------------------------------------

    def start(self):
        self.usd_context.open_stage_with_callback(self.usd_path, self.on_stage_loading_done)


# -------------------------------------------------------------------------
# CLI glue
# -------------------------------------------------------------------------


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("path", help="Path to USD stage.")
    parser.add_argument("--debug", action="store_true")
    parser.add_argument("--displayAov", type=str, default=None)
    parser.add_argument("--exitFrameCount", type=int, default=None)
    args = parser.parse_args()

    if args.debug:
        import debugpy

        debugpy.listen(("0.0.0.0", 3000))
        print("Waiting for python debugger to attach, listening on port 3000 ...")
        debugpy.wait_for_client()

    test = PostProcessingTest(usd_path=args.path, exit_frame_count=args.exitFrameCount, display_aov=args.displayAov)
    test.start()


if __name__ == "__main__":
    main()
